// A pending quote names the message the next send will reply to. It clears on
// the send that consumed it, on its cancel control, and whenever the pane
// moves to another conversation — a quote never crosses sessions.
const quoteReplyTarget = shallowRef<{ id: string, sender: string, preview: string } | null>(null)

function quoteMenuAvailable(message: ChatMessage) {
  return !!currentBotId.value
    && !activeChatReadOnly.value
    && (message.role === 'user' || message.role === 'assistant')
    && !message.streaming
    && !!message.id
}

function quotePreviewFor(message: ChatMessage) {
  const raw = message.role === 'user'
    ? message.text
    : message.role === 'assistant'
      ? message.messages
        .flatMap(block => block.type === 'text' ? [block.content] : [])
        .join(' ')
      : ''
  const flat = raw.replace(/\s+/g, ' ').trim()
  if (!flat) return ''
  return [...flat].length > 100 ? [...flat].slice(0, 100).join('') + '…' : flat
}

function startQuoteReply(message: ChatMessage) {
  if (!quoteMenuAvailable(message)) return
  const sender = message.role === 'assistant'
    ? currentBot.value?.display_name || currentBot.value?.name || ''
    : message.role === 'user'
      ? message.senderDisplayName || ''
      : ''
  quoteReplyTarget.value = { id: message.id, sender, preview: quotePreviewFor(message) }
}

function cancelQuoteReply() {
  quoteReplyTarget.value = null
}

watch(() => [paneTarget.value.botId, paneTarget.value.sessionId], () => {
  quoteReplyTarget.value = null
